import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static int nextInt() {
        while (pos < buf.length && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        if (pos >= buf.length) return -1;
        int ret = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') {
            ret = ret * 10 + (buf[pos++] - '0');
        }
        return ret;
    }

    public static void main(String[] args) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream(1 << 22);
        byte[] chunk = new byte[1 << 16];
        int r;
        while ((r = System.in.read(chunk)) != -1) {
            bos.write(chunk, 0, r);
        }
        buf = bos.toByteArray();
        pos = 0;

        int N = nextInt();
        int K = nextInt();
        int U = nextInt();

        int total = N * K;
        int[] cardNums = new int[total];
        int[] cnt = new int[U + 1];

        int p = 0;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < K; j++) {
                int x = nextInt();
                cardNums[p++] = x;
                cnt[x]++;
            }
        }

        // Índice invertido: números v ocupam o segmento [segStart[v], segStart[v+1]) em lists
        int[] segStart = new int[U + 2];
        for (int v = 1; v <= U; v++) segStart[v + 1] = segStart[v] + cnt[v];

        int[] lists = new int[total];
        int[] ptr = new int[U + 1];
        for (int v = 1; v <= U; v++) ptr[v] = segStart[v];

        p = 0;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < K; j++) {
                int x = cardNums[p++];
                lists[ptr[x]++] = i;
            }
        }

        int[] done = new int[N];
        ArrayList<Integer> winners = new ArrayList<>();

        for (int t = 0; t < U && winners.isEmpty(); t++) {
            int x = nextInt();
            for (int idx = segStart[x], end = segStart[x + 1]; idx < end; idx++) {
                int c = lists[idx];
                if (++done[c] == K) winners.add(c);
            }
        }

        Collections.sort(winners);
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        for (int w : winners) {
            if (!first) sb.append(' ');
            sb.append(w + 1);
            first = false;
        }
        System.out.println(sb);
    }
}
